"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["52977"],{17521(e){e.exports=JSON.parse('{"id":"FIN-321","slug":"producer-surplus","term":"Producer Surplus","also_known_as":[],"difficulty":"Intermediate","definition":"Producer surplus is the difference between the price a seller receives for a good and the minimum price at which they would have been willing to sell it. It measures the extra benefit producers gain from selling.","explanation":["Each producer has a minimum price at which they are willing to sell, usually related to their cost of production. If a farmer would sell tomatoes for as little as 1 per kilogram but the market price is 1.60, they gain 0.60 of producer surplus on each kilogram sold.","Across a whole market, producer surplus adds up these gains for all sellers. On a supply and demand graph, it is the area above the supply curve and below the market price, up to the quantity sold.","Producer surplus is closely linked to profit but is not identical, because it focuses on the gains from each extra sale above the minimum acceptable price rather than total profit after all fixed costs.","When prices rise, producer surplus grows, both for existing sellers and for new ones who enter the market. When prices fall, it shrinks. Consumer surplus and producer surplus together make up total surplus, a measure economists use to judge how much overall benefit a market creates for society."],"note":"","total":1725,"prev":{"slug":"producer-price-index","term":"Producer Price Index (PPI)"},"next":{"slug":"product-market-fit","term":"Product-Market Fit"}}')}}]);